args.sparql:
SELECT DISTINCT ?mother ?motherLabel WHERE {
  ?husband dbo:spouse dbr:Louise_of_Mecklenburg-G%C3%BCstrow .
  ?husband dbp:mother ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel }
  FILTER ( !bound(?motherLabel) || lang(?motherLabel) = "en" )
}

SELECT DISTINCT ?mother ?motherLabel WHERE {
  { ?husband dbo:spouse dbr:Louise_of_Mecklenburg-G%C3%BCstrow }
